import{_ as i,o as s,c as a,ah as r}from"./chunks/framework.CvRIgsZ1.js";const t="/projects/MentorPi-T1/en/latest/assets/image2.BDUD-mh7.webp",c="/projects/MentorPi-T1/en/latest/assets/image3.CbWaNjkH.webp",d="/projects/MentorPi-T1/en/latest/assets/image4.ChsIS_IC.webp",l="/projects/MentorPi-T1/en/latest/assets/image5.acrEScMz.webp",p="data:image/png;base64,",h="data:image/png;base64,",o="/projects/MentorPi-T1/en/latest/assets/image8.DzSO6Ce2.webp",g="/projects/MentorPi-T1/en/latest/assets/image9.D5C9i6EP.webp",m="/projects/MentorPi-T1/en/latest/assets/image10.CsF2aAr4.webp",n="data:image/png;base64,",u="/projects/MentorPi-T1/en/latest/assets/image14.MgO63BzP.webp",A="/projects/MentorPi-T1/en/latest/assets/image15.DdX0Gh3M.webp",b="/projects/MentorPi-T1/en/latest/assets/image18.BZPMyJvV.webp",v="/projects/MentorPi-T1/en/latest/assets/image19.jKby5H5E.webp",w="/projects/MentorPi-T1/en/latest/assets/image20.-MQYX2Ez.webp",y="/projects/MentorPi-T1/en/latest/assets/image21.BJHQH21O.webp",k="/projects/MentorPi-T1/en/latest/assets/image22.tFD14u-I.webp",f="/projects/MentorPi-T1/en/latest/assets/image23.DbUhc1Jo.webp",q="/projects/MentorPi-T1/en/latest/assets/image24.azgCgdgI.webp",M="/projects/MentorPi-T1/en/latest/assets/image25.D_VdXlB7.webp",C="/projects/MentorPi-T1/en/latest/assets/image26.Bne5appu.webp",P="/projects/MentorPi-T1/en/latest/assets/image21.BDFbRWXH.webp",W="/projects/MentorPi-T1/en/latest/assets/image28.C0g4NYbL.webp",x="/projects/MentorPi-T1/en/latest/assets/image29.Csfp4gV5.webp",z=JSON.parse('{"title":"13. Robot Network Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"docs/13.robot_network_configuration.md","filePath":"docs/13.robot_network_configuration.md"}'),E={name:"docs/13.robot_network_configuration.md"};function T(N,e,O,I,S,F){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_13-robot-network-configuration" tabindex="-1">13. Robot Network Configuration <a class="header-anchor" href="#_13-robot-network-configuration" aria-label="Permalink to &quot;13. Robot Network Configuration&quot;">​</a></h1><h2 id="_13-1-network-configuration-overview" tabindex="-1">13.1 Network Configuration Overview <a class="header-anchor" href="#_13-1-network-configuration-overview" aria-label="Permalink to &quot;13.1 Network Configuration Overview&quot;">​</a></h2><p>The robot&#39;s network can be configured in two modes:</p><p>(1) AP Mode: The controller creates a hotspot that can be connected to by a smartphone. (Note: This mode does not connect to the external internet.)</p><p>(2) STA mode: The controller connects directly to a specified hotspot/Wi-Fi network. (This mode allows access to the external internet.)</p><p>By default, the robot operates in AP (direct connection) mode. The features and functions of the robot remain the same whether in AP mode or STA (local area network) mode.</p><h2 id="_13-2-ap-direct-connection-mode" tabindex="-1">13.2 AP Direct Connection Mode <a class="header-anchor" href="#_13-2-ap-direct-connection-mode" aria-label="Permalink to &quot;13.2 AP Direct Connection Mode&quot;">​</a></h2><h3 id="_13-2-1-mode-switching-through-phone" tabindex="-1">13.2.1 Mode Switching through Phone <a class="header-anchor" href="#_13-2-1-mode-switching-through-phone" aria-label="Permalink to &quot;13.2.1 Mode Switching through Phone&quot;">​</a></h3><p>Using the Android system as an example, these instructions also apply to iOS.</p><p>(1) Open the <strong>&quot;WonderPi&quot;</strong> app on your phone. Then, go to <strong>&quot;Advanced&quot;</strong> and select <strong>&quot;MentorPi T1&quot;</strong>.</p><img loading="lazy" height="576" width="1219" src="'+t+'" class="common_img"><p>(2) Tap the <strong>&quot;+&quot;</strong> button in the bottom right corner of the screen, and choose <strong>&quot;Direct Connection Mode&quot;</strong>.</p><img loading="lazy" height="539" width="1065" src="'+c+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If you prefer to connect in LAN mode, refer to <code>13.3 Connecting in LAN Mode (optional)</code>.</p></section><p>(3) Tap <strong>&quot;Go to Connect Device Hotspot&quot;</strong>. This will take you to your phone’s settings to connect to the hotspot created by the robot.</p><img loading="lazy" height="538" width="1068" src="'+d+'" class="common_img"><p>(4) Look for a hotspot name starting with <strong>&quot;HW&quot;</strong>. The password is <strong>&quot;hiwonder&quot;</strong>.</p><img loading="lazy" height="264" width="755" src="'+l+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>For iOS: Wait until the Wi-Fi icon <img loading="lazy" height="52" width="52" src="'+p+'"> appears in your phone’s status bar before returning to the app. If you don’t see the device listed, you can refresh by tapping the refresh icon <img loading="lazy" height="52" width="52" src="'+h+'"> in the upper-right corner of the app.</p></section><p>(5) Return to the app, and tap the robot icon to enter the mode selection screen.</p><img loading="lazy" height="576" width="1219" src="'+o+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If a pop-up message appears saying <strong>&quot;Network Unavailable, Continue Connection?&quot;</strong>, simply tap <strong>&quot;Keep Connection&quot;</strong>.</p></section><p>(6) If you see a prompt asking <strong>&quot;Whether to switch to and enter the searched interface?&quot;</strong>, it indicates that an incorrect product version was selected in Step 1. Tap <strong>&quot;CONFIRM&quot;</strong> to switch directly to the correct version’s mode selection screen.</p><img loading="lazy" height="576" width="1218" src="'+g+'" class="common_img"><p>(7) The mode selection screen appears as shown below:</p><img loading="lazy" height="576" width="1219" src="'+m+'" class="common_img"><p>For details on each mode, refer to the documentation provided earlier.</p><h3 id="_13-2-2-switching-via-network-configuration-file" tabindex="-1">13.2.2 Switching via Network Configuration File <a class="header-anchor" href="#_13-2-2-switching-via-network-configuration-file" aria-label="Permalink to &quot;13.2.2 Switching via Network Configuration File&quot;">​</a></h3><p>(1) Power on the robot and connect it to the remote control software, VNC.</p><p>(2) Double-click the terminal icon <img loading="lazy" height="32" width="46" src="'+n+'"> on the desktop to open the command line terminal.</p><p>(3) Enter the command <code>cd hiwonder-toolbox/</code> and press Enter to navigate to the configuration file directory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox/</span></span></code></pre></div><p>(4) Enter the command <code>vim wifi_conf.py</code> and press Enter to open the configuration file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim wifi_conf.py</span></span></code></pre></div><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The configuration file defaults to AP Direct Connection Mode. If all code lines are commented out, it will be set to AP Direct Connection Mode.</p></section><img loading="lazy" height="476" width="748" src="'+u+'" class="common_img"><p>(5) If there are multiple devices nearby, you can modify <code>HW_WIFI_AP_SSID</code> and <code>HW_WIFI_AP_PASSWORD</code> to set a unique name and password for each device. For example, use <strong>&quot;HW-Robot&quot;</strong> as the name and <strong>&quot;hiwonder&quot;</strong> as the password, as shown below.</p><img loading="lazy" height="249" width="748" src="'+A+'" class="common_img"><p>(6) After verifying the entries, press the ESC key, then type <code>:wq</code> to save and exit the file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><p>(7) Enter the command <code>sudo systemctl restart wifi.service</code> to restart the robot&#39;s Wi-Fi service.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl restart wifi.service</span></span></code></pre></div><p>(8) Wait for the service to restart. You should see that the hotspot has been successfully updated.</p><img loading="lazy" height="44" width="342" src="'+b+'" class="common_img"><p>(9) To connect using VNC, enter the new IP address in the search bar, and click on the connection icon that appears. Log in with the username <strong>&quot;pi&quot;</strong> and password <strong>&quot;raspberrypi&quot;</strong>, then click <strong>&quot;OK&quot;</strong> to access the system desktop.</p><img loading="lazy" height="353" width="486" src="'+v+'" class="common_img"><img loading="lazy" height="1008" width="1794" src="'+w+'" class="common_img"><h2 id="_13-3-connecting-in-lan-mode-optional" tabindex="-1">13.3 Connecting in LAN Mode (optional) <a class="header-anchor" href="#_13-3-connecting-in-lan-mode-optional" aria-label="Permalink to &quot;13.3 Connecting in LAN Mode (optional)&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>(1) To configure the LAN mode using a smartphone, you must first enable the phone&#39;s location services.</p><p>(2) Switching to LAN mode cannot be done directly through the system&#39;s network settings, as the Wi-Fi has custom configurations. Please follow the instructions in <code>13.3.2 Switching via Network Configuration File</code> to switch modes using the network configuration file.</p></section><h3 id="_13-3-1-switching-via-the-mobile-app" tabindex="-1">13.3.1 Switching via the Mobile App <a class="header-anchor" href="#_13-3-1-switching-via-the-mobile-app" aria-label="Permalink to &quot;13.3.1 Switching via the Mobile App&quot;">​</a></h3><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>For LAN mode, please enable location services on your smartphone.</p></section><p>(1) First, connect your phone to Wi-Fi. In this example, we connect to <strong>&quot;Hiwonder_5G&quot;</strong> Wi-Fi. (For dual-band routers with separated frequencies, the Wi-Fi names may differ, such as <strong>&quot;Hiwonder&quot;</strong> for the 2.4G band and <strong>&quot;Hiwonder_5G&quot;</strong> for the 5G band.)</p><img loading="lazy" height="1207" width="1055" src="'+y+'" class="common_img" style="width:400px;"><p>(2) Open the <strong>&quot;WonderPi&quot;</strong> app on your phone, then select <strong>&quot;Advanced&quot;</strong> and <strong>&quot;MentorPi&quot;</strong>.</p><img loading="lazy" height="576" width="1219" src="'+t+'" class="common_img"><p>(3) Tap the <strong>&quot;+&quot;</strong> button in the bottom right corner, and choose <strong>&quot;LAN Mode&quot;</strong>.</p><img loading="lazy" height="414" width="902" src="'+k+'" class="common_img"><p>(4) The app will prompt you to enter the password for the connected Wi-Fi network. (Please ensure the password is correct, as an incorrect password will result in connection failure.) After entering the password, tap <strong>&quot;OK&quot;</strong>.</p><img loading="lazy" height="591" width="1271" src="'+f+'" class="common_img"><p>(5) Tap <strong>&quot;Go to connect device hotspot&quot;</strong>.</p><img loading="lazy" height="554" width="1264" src="'+q+'" class="common_img"><p>(6) Your phone will automatically navigate to the Wi-Fi settings page. Find the hotspot starting with <strong>&quot;HW&quot;</strong> and enter the password <strong>&quot;hiwonder&quot;</strong>. Once connected, tap the <strong>&quot;Return&quot;</strong> button.</p><img loading="lazy" height="295" width="345" src="'+M+'" class="common_img"><p>(7) The app will now begin the connection process.</p><img loading="lazy" height="567" width="1267" src="'+C+'" class="common_img"><p>(8) After a short wait, the robot’s icon will appear on the main screen, and the LED on the expansion board will remain steadily lit.</p><img loading="lazy" height="576" width="1219" src="'+o+'" class="common_img"><p>(9) Press and hold the robot icon in the app to view the robot’s assigned IP address and device ID.</p><img loading="lazy" height="576" width="1219" src="'+P+'" class="common_img"><p>(10) Use a remote desktop tool to search for the robot&#39;s IP address and connect to the remote desktop.</p><p>(11) To switch back to direct connection mode from LAN mode, press and hold the <code>KEY1</code> button on the expansion board until the blue LED flashes, indicating that the switch is complete.</p><h3 id="_13-3-2-switching-via-network-configuration-file" tabindex="-1">13.3.2 Switching via Network Configuration File <a class="header-anchor" href="#_13-3-2-switching-via-network-configuration-file" aria-label="Permalink to &quot;13.3.2 Switching via Network Configuration File&quot;">​</a></h3><p>(1) Power on the robot and connect it to the remote control software, NoMachine.</p><p>(2) Click the terminal icon <img loading="lazy" height="32" width="46" src="'+n+`"> at the top of the system screen to open the command line terminal.</p><p>(3) Enter the command and press Enter to access the configuration file directory.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><p>(4) Enter the command and press Enter to open the configuration file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim wifi_conf.py</span></span></code></pre></div><p>(5) First, change the value of <code>HW_WIFI_MODE</code> to 2:</p><pre><code>- 1 represents Direct Connection Mode
- 2 represents LAN Mode
- 3 represents Direct Sharing Mode
</code></pre><img loading="lazy" height="25" width="812" src="`+W+'" class="common_img"><p>(6) Next, modify <code>HW_WIFI_STA_SSID</code> and <code>HW_WIFI_STA_PASSWORD</code> to match your router’s Wi-Fi name and password.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Selecting a 5G Wi-Fi signal will provide higher transfer speeds. If there is lag on standard Wi-Fi, consider switching to a 5G signal.</p></section><img loading="lazy" height="227" width="727" src="'+x+'" class="common_img"><p>(7) After confirming the entries are correct, press the ESC key, then type <code>:wq</code> to save and exit the file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><p>(8) Enter the following command to restart the robot&#39;s Wi-Fi service.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl restart wifi.service</span></span></code></pre></div><p>(9) To switch back to Direct Connection Mode, edit the configuration file again, comment out all lines, save, and restart.</p>',89)])])}const _=i(E,[["render",T]]);export{z as __pageData,_ as default};
